data.query:
query Query(
  $P: ProductWhereInput,
  $PS: ProductStrategyWhereInput
) {
  product(where: $P) {
    edges {
      node {
        id
        active
        externalId
        integrationData
        productTypeId
        strategies(where: $PS) {
          edges {
            node {
              active
              primary
              validated
              externalId
              effectiveAt
              expirationAt
              integrationData
              strategyTypeId
            }
          }
        }
      }
    }
  }
}
